def inspect_affected_orders(report):
    """
    Inspect affected orders and summarize the likely issue.

    Args:
        report (dict): The report containing sales and return data.

    Returns:
        str: A summary of the likely issue.
    """
    has_pending_returns, pending_returns_count = check_pending_return_requests(report)

    if not has_pending_returns:
        return "No pending return requests found."

    affected_orders = report.get("returns", {}).get("affected_orders", [])

    if not affected_orders:
        return "No affected orders found."

    issue_summary = f"Pending return requests found for {pending_returns_count} orders. "
    issue_summary += f"Affected orders: {affected_orders}. "
    issue_summary += "Further investigation is required to determine the cause of the returns."

    return issue_summary

